			function GetCategory()
			{ // sample Business travel- air > Flights > Long-haul, to/from UK > Premium economy class
			 	var levels = ["Level 1", "Level 2", "Level 3", "Level 4"];
				var catVal = "";

				for (var i = 0; i < levels.length; i++) {
					var levelValue = window.external.GetCsvColumnValue(levels[i]);
					if (levelValue)
					{
						if (catVal !== "")
						{
							catVal += " > ";
						}
						catVal += levelValue;
					}
				}

				return catVal;
			}

			function Convert6Decimals()
			{
				var num = Number(window.external.GetCsvColumnValue("GHG Conversion Factor 2023"));
    			return num.toFixed(6);
			}
